#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <unistd.h>
static void record(const char *operation,const char *path,int flags) {
 char line[16384]; int n=snprintf(line,sizeof(line),"ACCESS %s %d ",operation,flags);
 for(const unsigned char *p=(const unsigned char *)path;*p && n+3<sizeof(line);p++) n+=snprintf(line+n,sizeof(line)-n,"%02x",*p);
 line[n++]='\n'; write(2,line,n);
}
static int observed_open(const char *path,int flags,...) {
 mode_t mode=0; if(flags&O_CREAT){va_list ap;va_start(ap,flags);mode=va_arg(ap,int);va_end(ap);}
 record("open",path,flags);return open(path,flags,mode);
}
static FILE *observed_fopen(const char *path,const char *mode) {
 record("fopen",path,mode[0]=='r'?O_RDONLY:O_WRONLY);return fopen(path,mode);
}
__attribute__((used)) static struct {const void *replacement;const void *original;} hooks[]
__attribute__((section("__DATA,__interpose"))) = {{(const void *)observed_open,(const void *)open},{(const void *)observed_fopen,(const void *)fopen}};
